const fs = require('fs');
const path = require('path');

// --- Seeded PRNG (mulberry32) ---
function mulberry32(seed) {
    return function() {
        seed |= 0;
        seed = seed = seed + 0x6D2B79F5 | 0;
        let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
}

// --- Parsing (same as data.js) ---
const GENRE_NAMES = [
    "unknown", "Action", "Adventure", "Animation", "Children's", "Comedy",
    "Crime", "Documentary", "Drama", "Fantasy", "Film-Noir",
    "Horror", "Musical", "Mystery", "Romance", "Sci-Fi",
    "Thriller", "War", "Western"
];

function parseItemData(text) {
    const movies = [];
    const lines = text.split('\n');
    for (const line of lines) {
        if (line.trim() === '') continue;
        const fields = line.split('|');
        if (fields.length < 24) continue;
        const id = parseInt(fields[0]);
        const title = fields[1];
        const vector = fields.slice(5, 24).map(v => parseInt(v));
        const genres = GENRE_NAMES.filter((_, i) => vector[i] === 1);
        movies.push({ id, title, genres, vector });
    }
    return movies;
}

function parseRatingData(text) {
    const ratings = [];
    const lines = text.split('\n');
    for (const line of lines) {
        if (line.trim() === '') continue;
        const fields = line.split('\t');
        if (fields.length < 4) continue;
        ratings.push({
            userId: parseInt(fields[0]),
            itemId: parseInt(fields[1]),
            rating: parseFloat(fields[2]),
            timestamp: parseInt(fields[3])
        });
    }
    return ratings;
}

// --- Similarity ---
function cosine(a, b) {
    let dot = 0, normA = 0, normB = 0;
    for (let i = 0; i < a.length; i++) {
        dot += a[i] * b[i];
        normA += a[i] * a[i];
        normB += b[i] * b[i];
    }
    return (normA > 0 && normB > 0) ? dot / (Math.sqrt(normA) * Math.sqrt(normB)) : 0;
}

function dot(a, b) {
    let sum = 0;
    for (let i = 0; i < a.length; i++) sum += a[i] * b[i];
    return sum;
}

function genreCount(movie) {
    return movie.vector.reduce((a, b) => a + b, 0);
}

// --- Top-k retrieval ---
function getTopK(scoreFn, query, candidates, excludeIds, k, tieBreakMode, randomKeys) {
    const scored = [];
    for (const m of candidates) {
        if (excludeIds && excludeIds.has(m.id)) continue;
        scored.push({ id: m.id, movie: m, score: scoreFn(query, m.vector) });
    }

    if (tieBreakMode === 'random') {
        scored.sort((a, b) => b.score - a.score || randomKeys.get(a.id) - randomKeys.get(b.id));
    } else {
        scored.sort((a, b) => b.score - a.score || a.id - b.id);
    }

    return scored.slice(0, k);
}

// --- Load data ---
