const dataPath = path.join(__dirname, '..', 'u.data');
const itemText = fs.readFileSync(itemPath, 'latin1');
const dataText = fs.readFileSync(dataPath, 'latin1');

const movies = parseItemData(itemText);
const ratings = parseRatingData(dataText);
const movieById = new Map(movies.map(m => [m.id, m]));

// --- Popularity ---
const popularity = new Map();
for (const r of ratings) {
    popularity.set(r.itemId, (popularity.get(r.itemId) || 0) + 1);
}
// Movies with 0 ratings
for (const m of movies) {
    if (!popularity.has(m.id)) popularity.set(m.id, 0);
}

// --- Head/long-tail split ---
const totalRatings = ratings.length;
const sortedByPop = [...movies].sort((a, b) => (popularity.get(b.id) || 0) - (popularity.get(a.id) || 0));
let cumulative = 0;
const headIds = new Set();
for (const m of sortedByPop) {
    if (cumulative >= totalRatings * 0.5) break;
    headIds.add(m.id);
