     const topB = topK(cosine, profVec, movies, p.rated, 5, 'id', randomKeys);

     const idsA = new Set(topA.map(x => x.id));
     const idsB = new Set(topB.map(x => x.id));
     let ov = 0;
     for (const id of idsA) if (idsB.has(id)) ov++;
