]);

p('**Why id-ascending tie-breaking inflates popularity:** mean rating count by id range.');
p('');
table(['ID range', 'n movies', 'Mean popularity (rating count)'], [
    ['id <= 400', String(a3_nLe400), fmt(a3_meanPopLe400, 2)],
